"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["86243"],{89714(e){e.exports=JSON.parse('{"id":"V4-027","slug":"registered-retirement-savings-plan","term":"Registered Retirement Savings Plan (RRSP)","also_known_as":[],"difficulty":"Intermediate","definition":"A Registered Retirement Savings Plan (RRSP) is a tax-advantaged retirement savings account in Canada, in which contributions are deductible from taxable income and investments grow tax-deferred until withdrawal.","explanation":["RRSPs encourage Canadians to save for retirement. Contributions reduce taxable income in the year they are made or a later year, up to a contribution limit based mainly on the previous year\u2019s earned income. Unused contribution room can be carried forward.","Investments inside an RRSP, such as funds, shares, bonds and deposits, grow without tax until money is withdrawn. Withdrawals are taxed as income, ideally in retirement, when the person may be in a lower tax bracket.","For example, someone in a 30% tax bracket who contributes 10,000 to an RRSP could reduce their tax bill by about 3,000 that year.","By the end of the year in which the holder turns 71, the RRSP must be closed, usually by converting it into a Registered Retirement Income Fund, which pays income with minimum annual withdrawals, or by buying an annuity. Special programmes allow withdrawals to buy a first home or fund education, to be repaid later. RRSPs are often compared with Tax-Free Savings Accounts; which suits a person better depends largely on their current and expected future tax rates."],"note":"","total":1725,"prev":{"slug":"registered-investment-adviser","term":"Registered Investment Adviser"},"next":{"slug":"regression-analysis","term":"Regression Analysis"}}')}}]);